//chains together components- each has a position (anchor) and a pin (mechanism motion result). Last object pin = next object position

class Machine{
	constructor(){
		this.parts = [];
		this.periods = [];
		this.tick = 0;
		this.lastPin = null;
		this.workingPos = createVector(0,0);
		this.periodBase = 80;
		this.partRTypes = [];
		this.machinedParts = [];
		this.initRandom();
		this.bounds = null;
		this.renderx = 600;
		this.rendery = 600;
		this.lastPulleyOrientation = 1;
	}

	initRandom(){
		let builtRoller = false;
		let ktypes = ["ROTATOR", "ROCKER", "STATIONARY", "SLIDER", "LIFTER", "PULLEYWHEEL", "PENDULUM", "SQWHEEL"];
		let driverEngine = new PistonWheel(createVector(100, 0), createVector(500, 0), 100);
		this.parts.push(driverEngine);
		this.partRTypes.push("MACHINED");
		this.machinedParts.push(machinedPart(200,80));
		this.lastPin = driverEngine.pin;
		let lastType = "ENGINE";
		for (let i = 0; i < 9; i++){

			if (lastType == "PULLEYWHEEL"){
				if (!builtRoller){
					builtRoller = true;
					this.addPart("ROLLERRAMP");
					this.addPart("PENDULUM");
				}
			}
			//pullywheel should only be chained to a component that can hold the rope
			let rtype = ktypes[floor(random(ktypes.length))];
			if (rtype == "PULLEYWHEEL"){
				if (lastType == "PULLEYWHEEL" || lastType == "LIFTER"){
					while(rtype == "PULLEYWHEEL"){
						rtype = ktypes[floor(random(ktypes.length))];
					}
				}
			}
			//chaining pendulum to pendulum is chaos, dont do it!
			if (rtype == "PENDULUM"){
				if (lastType == "PULLEYWHEEL" || lastType == "PENDULUM"){
					while(rtype == "PENDULUM" || rtype == "PULLEYWHEEL"){
						rtype = ktypes[floor(random(ktypes.length))];
					}
				}
			}
			this.addPart(rtype);
			lastType = rtype;
		}
	}

	getRandomPin(){
		if (this.parts.length < 2){
			return null;
		}
		let iter = 0;
		while (iter < 10){
			iter++;
			let rpart = this.parts[floor(random(this.parts.length))];
			if (rpart.pin != null){
				return rpart.pin;
			}
		}
		return null;
	}

	update(){
		this.tick++;
		let bper = this.periodBase * 2;
		let tk = (this.tick % bper) / bper;
		let tv = abs(sin(tk * TWO_PI));
		tv = easeInOutCubic(tv);
		for (let i = 0; i < this.parts.length; i++){
			let p = this.parts[i];
			if (p.tweenMode){
				p.tv = tv;
			}
			p.update();
			p.render();
			let prt = this.partRTypes[i];
			if (prt != null){
				let px = p.pin.x;
				let py = p.pin.y;
				if (prt == "MACHINED"){
					px = p.position.x;
					py = p.position.y;
				}
				this.renderPart(i, px, py, prt, p.position);
			}
		}
		if (this.bounds == null){
			this.bounds = this.getBounds();
			let centerScreenx = width * 0.5;
			let centerScreeny = height * 0.5;
			let centerbx = this.bounds.x + (this.bounds.w * 0.5);
			let centerby = this.bounds.y + (this.bounds.h * 0.5);
			this.renderx = centerScreenx - centerbx;
			this.rendery = centerScreeny - centerby;
		}
	}
	getBounds(){
		let minx = 10000;
		let miny = 10000;
		let maxx = -10000;
		let maxy = -10000;

		for (let i = 0; i < this.parts.length; i++){
			let p = this.parts[i];
			if (p.pin.x < minx){
				minx = p.pin.x;
			}
			if (p.position.x < minx){
				minx = p.position.x;
			}
			if (p.pin.x > maxx){
				maxx = p.pin.x;
			}
			if (p.position.x > maxx){
				maxx = p.position.x;
			}
			if (p.pin.y < miny){
				miny = p.pin.y;
			}
			if (p.position.y < miny){
				miny = p.position.y;
			}
			if (p.pin.y > maxy){
				maxy = p.pin.y;
			}
			if (p.position.y > maxy){
				maxy = p.position.y;
			}
		}

		return {x:minx, y:miny, w:maxx - minx, h:maxy - miny};
	}

	addPart(intype){
		if (this.lastPin == null){
			this.lastPin = createVector(this.workingPos.x, this.workingPos.y);
		}
		let pmult = 1 + floor(random(3));
		let np;
		switch(intype){
			case "ROTATOR":
				let rrad = 20 + random(60);
				np = new Wheel(this.lastPin, rrad);

				np.setPeriod(this.periodBase * pmult);
				this.parts.push(np);
				this.lastPin = np.pin;
				this.partRTypes.push("LINK");
				this.machinedParts.push(null);
				if (random(1) > 0.6){
					let gwpos = p5.Vector.fromAngle(random(TWO_PI));
					gwpos.setMag(rrad + random(100));
					gwpos.add(np.position);
					let np2 = new GearWheel(np, gwpos, true);
					this.parts.push(np2);
					this.partRTypes.push(null);
					this.machinedParts.push(null);
					this.lastPin = np2.pin;
				}
			break;
			case "ROCKER":
				let rlen = 20 + random(40);
				let amin = QUARTER_PI;
				let amax = PI;
				np = new Rocker(this.lastPin, rlen, amin, amax);
				np.period = this.periodBase * pmult;
				this.parts.push(np);
				this.lastPin = np.pin;
				np.tweenMode = true;
				this.partRTypes.push("LINK");
				this.machinedParts.push(null);
			break;
			case "STATIONARY":
				let dlen = 20 + random(40);
				np = new DLinkage(this.lastPin, 0, dlen);
				this.parts.push(np);
				this.lastPin = np.pin;
				this.partRTypes.push("MACHINED");
				this.machinedParts.push(machinedPart(120,120));
			break;
			case "SLIDER":
				let rpinner = this.getRandomPin();
				if (rpinner != null && rpinner != this.lastPin){
					np = new Slider(this.lastPin, rpinner);
					this.parts.push(np);
					this.lastPin = np.pin;
					this.partRTypes.push("LINK");
					this.machinedParts.push(null);
				}

			break;
			case "LEVER":
				let rslen = 40 + random(40);
				let lslen = 40 + random(40);
				np = new Lever(this.lastPin, rslen, lslen);
				this.parts.push(np);
				this.lastPin = np.pin;
				this.partRTypes.push("LINK");
				this.machinedParts.push(null);
				let rlock = this.getRandomPin();
				if (rlock != null){
					np.alock = rlock;

				}
			break;
			case "LIFTER":
				let rhgt = 40 + random(60);
				np = new Lifter(this.lastPin, rhgt);
				this.parts.push(np);
				this.lastPin = np.pin;
				this.partRTypes.push("MACHINED");
				this.machinedParts.push(machinedPart(100,80));
			break;
			case "PULLEYWHEEL":
				let ry = this.lastPin.y - 100 - random(100);
				let rx = this.lastPin.x + 50 + random(200);
				if (this.lastPulleyOrientation == 1){
					rx = this.lastPin.x - 50 - random(200);
				}
				let rrrad = 40 + random(60);
				np = new PulleyWheel(createVector(rx, ry), rrrad, this.lastPin, 300);
				this.parts.push(np);
				this.lastPin = np.pin;
				this.partRTypes.push(null);
				this.machinedParts.push(null);
				np.update();
				this.lastPulleyOrientation = np.srcLeft ? 1 : -1;
			break;
			case "ROLLERRAMP":
				let plen = 200 + random(100);
				let lpcopy = this.lastPin;
				let stablep;
				if (this.lastPulleyOrientation == -1){
					stablep = createVector(this.lastPin.x + plen, this.lastPin.y);
					this.lastPin = createVector(stablep.x + 200, stablep.y + 50);
				}else{
					stablep = createVector(this.lastPin.x - plen, this.lastPin.y);
					this.lastPin = createVector(stablep.x - 200, stablep.y + 50);
				}

				this.addPart("CAMWHEEL");
				this.addPart("PULLEYWHEEL");
				np = new RollerLine(lpcopy, this.lastPin, 60);
				this.parts.push(np);
				this.lastPin = np.pin;
				this.partRTypes.push(null);
				this.machinedParts.push(null);
			break;
			case "PENDULUM":
				let stringlen = 150 + random(150);
				np = new Pendulum(this.lastPin, stringlen);
				this.parts.push(np);
				this.partRTypes.push(null);
				this.machinedParts.push(null);
				this.lastPin = np.pin;
			break;
			case "CAMWHEEL":
				let crad1 = 20 + random(20);
				let crad2 = 60 + random(100);
				np = new CamWheel(this.lastPin, crad1, crad2, 0.05);
				this.parts.push(np);
				this.partRTypes.push(null);
				this.machinedParts.push(null);
				this.lastPin = np.pin;
			break;
			case "SQWHEEL":
				let slen = 50 + random(100);
				np = new SquareWheel(this.lastPin, slen);
				this.parts.push(np);
				this.partRTypes.push(null);
				this.machinedParts.push(null);
				this.lastPin = np.pin;
			break;
		}
	}

	renderPart(id, px, py, partType, nextPos=null, partw=40, parth=80, ang=0)
	{
		let cx;
		let cy;
		switch(partType){
			case "LINK":
				let posA = createVector(px,py);
				let posB;
				if (nextPos != null){
					posB = createVector(nextPos.x, nextPos.y);
				}else{
					posB = p5.Vector.fromAngle(ang);
					posB.setMag(parth);
					posB.add(posA);
				}

				let lvec = p5.Vector.sub(posB, posA);
				lvec.rotate(HALF_PI);
				lvec.setMag(partw * 0.5);
				beginShape();
				vertex(posA.x + lvec.x, posA.y + lvec.y);
				vertex(posB.x + lvec.x, posB.y + lvec.y);
				vertex(posB.x - lvec.x, posB.y - lvec.y);
				vertex(posA.x - lvec.x, posA.y - lvec.y);
				endShape();
				//line(posA.x + lvec.x, posA.y + lvec.y, posB.x + lvec.x, posB.y + lvec.y);
				//line(posA.x - lvec.x, posA.y - lvec.y, posB.x - lvec.x, posB.y - lvec.y);
				let lvh = lvec.heading();
				arc(posA.x, posA.y, partw, partw, lvh, lvh + PI);
				arc(posB.x, posB.y, partw, partw, lvh + PI, lvh + TWO_PI);
			break;
			case "BOX":
				cx = px - (partw * 0.5);
				cy = py - (parth * 0.5);
				rect(cx, cy, partw, parth);
			break;
			case "CAPSULE":
				cx = px - (partw * 0.5);
				cy = py - (parth * 0.5);
				rect(cx, cy, partw, parth, partw * 0.5, partw * 0.5);
			break;
			case "MACHINED":
				let mpart = this.machinedParts[id];
				mpart.renderAt(px, py)

			break;
		}
	}
}

