//class for generating polygonal shapes using PolyBool.js
//https://github.com/velipso/polybooljs
//only implements union via addPoly, todo: intersection, difference
/*
var segments = PolyBool.segments(polygon);
var combined = PolyBool.combine(segments1, segments2);
var segments = PolyBool.selectUnion(combined);
var segments = PolyBool.selectIntersect(combined);
var segments = PolyBool.selectDifference(combined);
var segments = PolyBool.selectDifferenceRev(combined);
var segments = PolyBool.selectXor(combined);
var polygon  = PolyBool.polygon(segments);
*/

class PolyBuilder {
	constructor() {
		this.poly = [];
		this.accumulator = null;
	}
	addPoly(polyObj, type="UNION") {
		this.poly.push(polyObj);
		if (this.accumulator == null) {
			this.accumulator = polyObj;
		} else {

			//this.accumulator = PolyBool.union(this.accumulator, polyObj);
			let segmentsA = PolyBool.segments(this.accumulator);
			let segmentsB = PolyBool.segments(polyObj);
			var combo = PolyBool.combine(segmentsA, segmentsB);
			if (type == "UNION"){
				segmentsA = PolyBool.selectUnion(combo);
			}else if (type == "XOR"){
				segmentsA = PolyBool.selectXor(combo);
			}else if (type == "INTERSECTION"){
				segmentsA = PolyBool.selectIntersect(combo);
			}

			this.accumulator = PolyBool.polygon(segmentsA);

		}
	}

	renderAt(px, py) {
		//render with a positional offset
		for (let r = 0; r < this.accumulator.regions.length; r++) {
			let rgns = this.accumulator.regions[r];
			beginShape();
			for (let i = 0; i < rgns.length; i++) {
				let rgn = rgns[i];
				let rpx = rgn[0];
				let rpy = rgn[1];
				vertex(rpx + px, rpy + py);
			}
			endShape();
		}
	}

	offset(dx, dy) {
		//permanently apply an offset to all vertices
		for (let r = 0; r < this.accumulator.regions.length; r++) {
			let rgns = this.accumulator.regions[r];
			//console.log(this.accumulator);
			for (let i = 0; i < rgns.length; i++) {
				let rgn = rgns[i];
				rgn[0] += dx;
				rgn[1] += dy;
			}
		}
	}

	inflateFrom(sx, sy, amt, rad, falloff = 1) {
		//does not work correctly, vertices can be pushed to create negative clipping
		//polybool union on result?
		for (let r = 0; r < this.accumulator.regions.length; r++) {
			let rgns = this.accumulator.regions[r];
			for (let i = 0; i < rgns.length; i++) {
				let rgn = rgns[i];
				let x = rgn[0];
				let y = rgn[1];
				let dx = x - sx;
				let dy = y - sy;
				let offset = createVector(dx, dy);
				let dst = offset.mag();
				if (dst <= rad) {
					if (falloff == 1) {
						dst += amt;
					} else {
						let pwr = 1 - (dst / rad);
						pwr *= falloff;
						dst += (pwr * amt);
					}
					offset.setMag(dst);
					rgn[0] = x + offset.x;
					rgn[1] = y + offset.y;
				}
			}
		}
	}

	getRect(rcx, rcy, rcw, rch) {
		//get a rectangle object that is ready for polybool operations
		let region = [];
		let pts0 = [rcx, rcy];
		let pts1 = [rcx + rcw, rcy];
		let pts2 = [rcx + rcw, rcy + rch];
		let pts3 = [rcx, rcy + rch];
		region.push(pts0);
		region.push(pts1);
		region.push(pts2);
		region.push(pts3);
		let rpoly = {
			regions: [region],
			inverted: false
		};
		return rpoly;
	}

	getRounderRect(rcx, rcy, rcw, rch, cpts = 3) {
		//get a rounded rectangle for polybool operations
		let region = [];
		let longerSide = (rcw > rch) ? rcw : rch;
		if (cpts > 6) {
			cpts = 6;
		}
		let inset = map(cpts, 1, 6, longerSide * 0.05, longerSide * 0.1);

		let c0 = this.cornerPoints(0, rcx + inset, rcy + inset, inset, cpts);
		region.push(...c0);
		let c1 = this.cornerPoints(1, rcx + rcw - inset, rcy + inset, inset, cpts);
		region.push(...c1);
		let c2 = this.cornerPoints(2, rcx + rcw - inset, rcy + rch - inset, inset, cpts);
		region.push(...c2);
		let c3 = this.cornerPoints(3, rcx + inset, rcy + rch - inset, inset, cpts);
		region.push(...c3);
		let rpoly = {
			regions: [region],
			inverted: false
		};
		return rpoly;
	}

	cornerPoints(whichCorner, anchorx, anchory, rad, npts) {
		//rounded corner of radius rad where anchor point is inside shape
		let outpts = [];
		let angin = 0;
		let angout = HALF_PI;
		if (whichCorner == 0) {
			//upper left
			angin = PI;
			angout = PI + HALF_PI;
		} else if (whichCorner == 1) {
			//upper right
			angin = PI + HALF_PI;
			angout = TWO_PI;
		} else if (whichCorner == 2) {
			//lower right
			angin = 0;
			angout = HALF_PI;
		} else if (whichCorner == 3) {
			//lower left
			angin = HALF_PI;
			angout = PI;
		}
		let angstep = HALF_PI / (npts + 1);
		for (let i = 0; i < npts; i++) {
			let a = i * angstep;
			a += angin;
			let pv = p5.Vector.fromAngle(a);
			pv.setMag(rad);
			outpts.push([anchorx + pv.x, anchory + pv.y]);
		}
		let lpv = p5.Vector.fromAngle(angout);
		lpv.setMag(rad);
		outpts.push([anchorx + lpv.x, anchory + lpv.y]);
		return outpts;
	}

	combLine(startx, starty, endx, endy, blockh, blockw) {
		//square wave line
		//    ______    ______
		//    |    |    |    |
		//____     _____|    |_____
		let lvec = createVector(endx - startx, endy - starty);
		let nblock = floor(lvec.mag() / blockw);
		let outpts = [];
		lvec.setMag(blockw);
		let perpVec = p5.Vector.fromAngle(lvec.heading() + HALF_PI);
		perpVec.setMag(blockh);
		outpts.push([startx, starty]);
		let dir = 0;
		let cursorx = startx;
		let cursory = starty;
		for (let i = 0; i < nblock; i++) {
			cursorx += lvec.x;
			cursory += lvec.y;
			outpts.push([cursorx, cursory]);
			if (dir == 0) {
				cursorx += perpVec.x;
				cursory += perpVec.y;
				dir = 1;
			} else if (dir == 1) {
				cursorx -= perpVec.x;
				cursory -= perpVec.y;
				dir = 0;
			}
			outpts.push([cursorx, cursory]);
		}
		outpts.push([endx, endy]);
		return outpts;
	}

	addCombRect(rcx, rcy, rcw, rch, cmbw, cmbh, combSide) {
		//rectangle that looks like a comb with parallel gaps
		//works for industrial greebling effect
		let region = [];
		if (combSide == 0) {
			//top
			let cmb = this.combLine(rcx, rcy, rcx + rcw, rcy, cmbh, cmbw);
			region.push(...cmb);
		} else {
			region.push([rcx, rcy]);
			region.push([rcx + rcw, rcy]);
		}
		if (combSide == 1) {
			//right
			let cmb = this.combLine(rcx + rcw, rcy, rcx + rcw, rcy + rch, cmbh, cmbw);
			region.push(...cmb);
		} else {
			region.push([rcx + rcw, rcy]);
			region.push([rcx + rcw, rcy + rch]);
		}
		if (combSide == 2) {
			//bottom
			let cmb = this.combLine(rcx + rcw, rcy + rch, rcx, rcy + rch, cmbh, cmbw);
			region.push(...cmb);
		} else {
			region.push([rcx + rcw, rcy + rch]);
			region.push([rcx, rcy + rch]);
		}
		if (combSide == 3) {
			//left
			let cmb = this.combLine(rcx, rcy + rch, rcx, rcy, cmbh, cmbw);
			region.push(...cmb);
		} else {
			region.push([rcx, rcy + rch]);
			region.push([rcx, rcy]);
		}
		let rpoly = {
			regions: [region],
			inverted: false
		};
		this.addPoly(rpoly);
	}

	addRect(rcx, rcy, rcw, rch) {
		//union-add a rectangle
		let pr = this.getRect(rcx, rcy, rcw, rch);
		this.addPoly(pr);
	}

	addRounderRect(rcx, rcy, rcw, rch, cpts) {
		let pr = this.getRounderRect(rcx, rcy, rcw, rch, cpts);
		this.addPoly(pr);
	}

	addRectByCenter(rcx, rcy, rcw, rch) {
		let pr = this.getRect(rcx - (rcw * 0.5), rcy - (rch * 0.5), rcw, rch);
		this.addPoly(pr);
	}
	addRounderRectByCenter(rcx, rcy, rcw, rch, cpts = 6) {
		let pr = this.getRounderRect(rcx - (rcw * 0.5), rcy - (rch * 0.5), rcw, rch, cpts);
		this.addPoly(pr);
	}
	addCombRectByCenter(rcx, rcy, rcw, rch, combSide) {
		let cmbw = rcw / 3;
		let cmbh = rch / 10;
		if (combSide == 0 || combSide == 2) {
			cmbw = rcw / 10;
			cmbh = rch / 3;
		}
		this.addCombRect(rcx - (rcw * 0.5), rcy - (rch * 0.5), rcw, rch, cmbw, cmbh, combSide);
	}
}

