function tangentPoint(C, r, P, side) {
	let toP = p5.Vector.sub(P, C);
	let d = toP.mag();
	if (d <= r) return null; // P is inside the circle; no tangent
	let baseAngle = atan2(toP.y, toP.x);
	let offset = acos(r / d);
	let a = baseAngle + side * offset;
	return createVector(C.x + r * cos(a), C.y + r * sin(a));
}

function easeInOutQuint(x) {
	return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
