class RollerLine {
	//a cylinder rolling on a suspended plank
	constructor(inendA, inendB, inballrad) {
		this.endA = inendA;
		this.endB = inendB;
		this.ballRad = inballrad;
		this.ballPos = createVector(0, 0);

		this.ballVelocityX = 0.0;
		this.lineLen = p5.Vector.dist(inendA, inendB);
		this.ballLinearPos = this.lineLen * 0.5;
		this.pin = p5.Vector.lerp(inendA, inendB, 0.5);
		this.position = this.endA;
		this.flipped = this.endA.x > this.endB.x;
	}

	update() {
		let lineVec = this.flipped ? p5.Vector.sub(this.endA, this.endB) : p5.Vector.sub(this.endB, this.endA);
		let tiltAngle = lineVec.heading();
		let gravityAlong = sin(tiltAngle); // component of gravity along the plank
		this.ballVelocityX += (gravityAlong * 0.9); // tune the gravity strength

		//console.log(this.ballVelocityX);
		this.ballVelocityX *= 0.9;
		this.ballLinearPos += this.ballVelocityX;

		// clamp so the ball doesn't roll off
		this.lineLen = lineVec.mag();
		this.ballLinearPos = constrain(this.ballLinearPos, 0, this.lineLen);
	}

	render() {
		let lineVec = this.flipped ? p5.Vector.sub(this.endA, this.endB) : p5.Vector.sub(this.endB, this.endA);
		let tiltAngle = lineVec.heading();
		let perpVec = p5.Vector.fromAngle(tiltAngle + HALF_PI).setMag(10);

		beginShape();
		vertex(this.endA.x, this.endA.y);
		vertex(this.endB.x, this.endB.y);
		vertex(this.endB.x + perpVec.x, this.endB.y + perpVec.y);
		vertex(this.endA.x + perpVec.x, this.endA.y + perpVec.y);
		endShape(CLOSE);

		let alongVec = p5.Vector.fromAngle(tiltAngle).setMag(this.ballLinearPos);
		let liftVec = p5.Vector.fromAngle(tiltAngle + HALF_PI).setMag(-(this.ballRad / 2));
		this.ballPos.x = (this.flipped ? this.endB.x : this.endA.x) + alongVec.x + liftVec.x;
		this.ballPos.y = (this.flipped ? this.endB.y : this.endA.y) + alongVec.y + liftVec.y;

		this.pin.x = this.ballPos.x;
		this.pin.y = this.ballPos.y;

		circle(this.ballPos.x, this.ballPos.y, this.ballRad);
	}

}

class PulleyWheel {
	constructor(inpos, inrad, insrc, inropeLen) {
		this.position = inpos;
		this.rad = inrad;
		this.sourceConnector = insrc;
		this.ropeLen = inropeLen;
		this.srcDistRest = p5.Vector.dist(inpos, insrc);
		//console.log(this.srcDistRest);
		this.ropeOffset = 0;
		this.pin = createVector(0, 0);
		this.srcLeft = this.position.x > insrc.x;
	}

	update() {
		if (this.sourceConnector.y < this.position.y) {
			let diff = this.position.y - this.sourceConnector.y;
			this.position.y -= diff;
		}
		let currentDist = p5.Vector.dist(this.position, this.sourceConnector);
		//console.log(currentDist)
		this.ropeOffset = currentDist - this.srcDistRest;
		//console.log(this.ropeOffset);
		if (this.srcLeft) {
			this.pin.x = this.position.x + this.rad;
		} else {
			this.pin.x = this.position.x - this.rad;
		}
		this.pin.y = this.position.y + this.ropeLen - this.ropeOffset;
		this.pin.y = constrain(this.pin.y, this.position.y, this.position.y + this.ropeLen);

	}
	render() {
		circle(this.position.x, this.position.y, this.rad * 2);
		if (this.sourceConnector != null) {
			let t = tangentPoint(this.position, this.rad, this.sourceConnector, this.srcLeft ? 1 : -1);
			if (t != null) {
				line(t.x, t.y, this.sourceConnector.x, this.sourceConnector.y);
				//line(this.position.x, this.position.y - this.rad, this.sourceConnector.x, this.sourceConnector.y);
				if (this.srcLeft) {
					this.pin.x = this.position.x + this.rad;
				} else {
					this.pin.x = this.position.x - this.rad;
				}

				this.pin.y = this.position.y + this.ropeLen - this.ropeOffset;
				this.pin.y = constrain(this.pin.y, this.position.y, this.position.y + this.ropeLen);
				let lox = this.srcLeft ? this.position.x + this.rad : this.position.x - this.rad;
				line(lox, this.position.y, this.pin.x, this.pin.y);
				fill(100);
				circle(this.position.x, this.position.y, 15);
				fill(uM_colors[0]);
			} else {
				//console.log("tangent point null");
				if (this.sourceConnector.y < this.position.y) {
					let diff = this.position.y - this.sourceConnector.y;
					this.position.y -= diff;
				}
				if (this.srcLeft) {
					if (this.sourceConnector.x > (this.position.x - this.rad)) {
						let diff = this.sourceConnector.x - (this.position.x - this.rad);
						this.position.x += diff;
					}
				} else {
					if (this.sourceConnector.x < (this.position.x + this.rad)) {
						let diff = this.position.x - (this.sourceConnector.x + this.rad);
						this.position.x -= diff;
					}
				}
			}
		} else {
			console.log("PULLEY SOURCE IS NULL")
		}
	}
}

class CamWheel {
	//cam rotates, pushes its follower up and down
	constructor(inpos, inrad, inrad2, inavel) {
		this.position = inpos;
		this.rad1 = inrad;
		this.rad2 = inrad2;
		this.avelocity = inavel;
		this.ang = 0;
		this.pin = createVector(0, 0);
		this.followerOffset = 0;
	}
	update() {
		this.ang += this.avelocity;
		this.ang %= TWO_PI;
	}
	render() {
		let numverts = 32;
		let astep = TWO_PI / numverts;
		let topi = floor(map((this.ang + PI) % TWO_PI, 0, TWO_PI, 0, numverts));
		let topang = TWO_PI - HALF_PI;
		let closesttopang = 1000;  //maybe better to compare actual y than trying to find angle closest to -90 (up?)
		beginShape();
		for (let i = 0; i < numverts; i++) {
			let a = (i * astep) + this.ang;
			a %= TWO_PI;
			let offset = p5.Vector.fromAngle(a);
			let omag;
			if (i < (numverts * 0.5)) {
				omag = map(i, 0, numverts * 0.5, this.rad1, this.rad2);
			} else {
				omag = map(i, numverts * 0.5, numverts, this.rad2, this.rad1);
			}
			offset.setMag(omag);
			offset.add(this.position);
			vertex(offset.x, offset.y);

			let adiffy = abs(a - topang);
			if (adiffy < closesttopang) {
				closesttopang = adiffy;
				this.followerOffset = offset.y;
			}
		}
		endShape(CLOSE);
		rect(this.position.x - 100, this.followerOffset - 50, 200, 50);
		arc(this.position.x - 100, this.followerOffset - 25, 50, 50, HALF_PI, PI + HALF_PI);
		arc(this.position.x + 100, this.followerOffset - 25, 50, 50, PI + HALF_PI, TWO_PI + HALF_PI);
		fill(100);
		circle(this.position.x + 100, this.followerOffset - 25, 15);
		circle(this.position.x, this.position.y, 15);
		fill(uM_colors[0]);
		this.pin.x = this.position.x + 100;
		this.pin.y = this.followerOffset - 25;
	}
}

class Pendulum {
	constructor(inpos, inlen) {
		this.position = inpos;
		this.len = inlen;
		this.ang = HALF_PI; // angle from +x axis, or from vertical — pick one
		this.angVel = 0;
		this.angAcc = 0;
		this.damping = 0.995;
		this.gravity = 0.4;
		this.pin = createVector(0, 0);
		this.lastPosition = createVector(this.position.x, this.position.y);
		this.pivotVel = createVector(0, 0);
	}

	update() {
		// Pivot velocity this frame, and how it changed since last frame
		let pivotVelNow = p5.Vector.sub(this.position, this.lastPosition);
		let pivotAcc = p5.Vector.sub(pivotVelNow, this.pivotVel);
		this.pivotVel.set(pivotVelNow.x, pivotVelNow.y);

		let angleFromDown = this.ang - HALF_PI;

		// Gravity restoring torque
		this.angAcc = -(this.gravity / this.len) * sin(angleFromDown);

		// Pivot coupling: only the *change* in pivot velocity matters,
		// and only its tangential component relative to the string.
		// Tangent direction at current angle: (-sin(ang), cos(ang))
		let tangentX = -sin(this.ang);
		let tangentY = cos(this.ang);
		let pivotTangential = pivotAcc.x * tangentX + pivotAcc.y * tangentY;
		this.angAcc += -pivotTangential / this.len;

		this.angVel += this.angAcc;
		this.angVel *= this.damping;
		this.ang += this.angVel;

		let offset = p5.Vector.fromAngle(this.ang).mult(this.len);
		this.pin.set(this.position.x + offset.x, this.position.y + offset.y);

		this.lastPosition.set(this.position.x, this.position.y);
	}

	render() {
		line(this.position.x, this.position.y, this.pin.x, this.pin.y);
		circle(this.pin.x, this.pin.y, 15);
	}
}

class Piston {
	constructor(inpos, inLenA, inLenB, inEnd = null) {
		this.position = inpos;
		this.len_compressed = inLenA;
		this.len_extended = inLenB;
		this.ang = 0;
		this.tick = 0;
		this.period = 200;
		if (inEnd != null) {
			this.pin = inEnd;
			this.controlled = true;
		} else {
			this.pin = createVector(0, 0);
			this.controlled = false;
		}
		this.showCrosshead = false;
	}
	update() {
		this.tick++;
		this.tick %= this.period;
		let stv = sin((this.tick / this.period) * TWO_PI);
		stv = (stv + 1) * 0.5;
		let len = this.len_compressed + stv * (this.len_extended - this.len_compressed);
		if (this.controlled) {
			let pvec = createVector(this.pin.x - this.position.x, this.pin.y - this.position.y);
			this.ang = pvec.heading();
			let plen = p5.Vector.dist(this.position, this.pin);
			plen = constrain(plen, this.len_compressed, this.len_extended);
			let endp = p5.Vector.fromAngle(this.ang);
			endp.setMag(plen);
			this.pin.x = this.position.x + endp.x;
			this.pin.y = this.position.y + endp.y;
		} else {
			let endp = p5.Vector.fromAngle(this.ang);
			endp.setMag(len);
			this.pin.x = this.position.x + endp.x;
			this.pin.y = this.position.y + endp.y;
		}
	}
	render() {
		let basePartEnd = p5.Vector.fromAngle(this.ang);
		basePartEnd.setMag(this.len_compressed);
		basePartEnd.add(this.position);
		strokeWeight(8);
		line(this.position.x, this.position.y, basePartEnd.x, basePartEnd.y);
		if (this.showCrosshead) {
			let endist = p5.Vector.dist(basePartEnd, this.pin);
			let headpos = p5.Vector.fromAngle(this.ang);
			headpos.setMag(endist);
			//headpos.sub(basePartEnd);
			headpos.add(this.position);
			circle(headpos.x, headpos.y, 20);
			let pvec = p5.Vector.fromAngle(this.ang + HALF_PI);
			pvec.setMag(30);
			line(headpos.x + pvec.x, headpos.y + pvec.y, headpos.x - pvec.x, headpos.y - pvec.y);
		}
		strokeWeight(1);
		line(this.position.x, this.position.y, this.pin.x, this.pin.y);
	}
}

