class GearWheel {
	constructor(indriveWheel, inpos, insticky) {
		this.driver = indriveWheel;
		this.position = inpos;
		let d = p5.Vector.dist(this.driver.position, inpos);
		d -= this.driver.rad;
		this.rad = d;
		// ratio of driver to driven: how much driven turns per unit driver turn
		this.ratio = this.driver.rad / this.rad;
		this.pin = createVector(0, 0);
		this.ang = 0;
		this.driverLastAng = this.driver.ang;
		this.sticky = insticky;
		if (insticky) {
			this.offsetx = this.position.x - this.driver.position.x;
			this.offsety = this.position.y - this.driver.position.y;
		}
	}

	update() {
		let driverDelta = this.driver.ang - this.driverLastAng;
		// handle wraparound: angle jumps from ~TWO_PI back to ~0
		if (driverDelta > PI) {
			driverDelta -= TWO_PI;
		} else if (driverDelta < -PI) {
			driverDelta += TWO_PI;
		}
		this.driverLastAng = this.driver.ang;

		// meshed gears rotate opposite directions, scaled by radius ratio
		this.ang -= driverDelta * this.ratio;

		// keep angle in [0, TWO_PI) — handle negative values too
		this.ang = ((this.ang % TWO_PI) + TWO_PI) % TWO_PI;

		if (this.sticky) {
			this.position.x = this.driver.position.x + this.offsetx;
			this.position.y = this.driver.position.y + this.offsety;
		}
		this.pin.x = cos(this.ang) * this.rad + this.position.x;
		this.pin.y = sin(this.ang) * this.rad + this.position.y;
	}

	render() {
		noFill();
		strokeWeight(8);
		circle(this.position.x, this.position.y, this.rad * 2);
		strokeWeight(4);
		circle(this.position.x, this.position.y, this.rad * 1.5);
		strokeWeight(1);
		fill(color('black'));
		circle(this.position.x, this.position.y, 15);
		circle(this.pin.x, this.pin.y, 15);
	}
}

class Linkage {
	//basic straight linkage connects two points. posB always constrained to same length from posA
	constructor(inposA, inposB, inLen) {
		this.posA = inposA;
		this.posB = inposB;
		this.len = inLen;
		this.capsuleMode = true;
		this.position = this.posA;
		this.pin = this.posB;
	}
	update() {
		let abvec = createVector(this.posB.x - this.posA.x, this.posB.y - this.posA.y);
		abvec.setMag(this.len);
		this.posB.x = this.posA.x + abvec.x;
		this.posB.y = this.posA.y + abvec.y;
	}
	render() {
		this.update();
		if (this.capsuleMode) {
			//noFill();
			let lvec = p5.Vector.sub(this.posB, this.posA);
			//console.log("linkage length = "+lvec.mag());
			lvec.rotate(HALF_PI);
			lvec.setMag(10);
			line(this.posA.x + lvec.x, this.posA.y + lvec.y, this.posB.x + lvec.x, this.posB.y + lvec.y);
			line(this.posA.x - lvec.x, this.posA.y - lvec.y, this.posB.x - lvec.x, this.posB.y - lvec.y);
			let lvh = lvec.heading();
			arc(this.posA.x, this.posA.y, 20, 20, lvh, lvh + PI);
			arc(this.posB.x, this.posB.y, 20, 20, lvh + PI, lvh + TWO_PI);
		} else {
			line(this.posA.x, this.posA.y, this.posB.x, this.posB.y);
		}

	}
}

