		this.tick++;
		this.tick %= this.period;
		if (this.tick == 0) {
			this.direction *= -1;
		}
		this.progress = (this.tick / this.period);

	}
	render() {
		rect(this.position.x - 10, this.position.y - this.height, 20, this.height);
		let lfty = this.direction == 1 ? this.progress * this.height : this.height - (this.progress * this.height);
		rect(this.position.x - 15, this.position.y - lfty, 30, 8);
		this.pin.x = this.position.x + 15;
		this.pin.y = this.position.y - lfty;
	}
}

class Lever {
	//rod anchored at center fulcrum, two linkages extend always locked to same angle (lever is a solid straight line)
	constructor(incpos, inLenR, inLenL) {
		this.anchor = incpos;
		this.len = inLenR + inLenL;
		this.lenR = inLenR;
		this.lenL = inLenL;
		this.angle = 0;
		this.pinA = createVector(0, 0);
		this.pinB = createVector(0, 0);
		this.pin = this.pinB;
		this.alock = null;
		this.position = this.anchor;
	}
	updateAngle_connectionA(connectionA) {
		//if pinA needs to remain locked to a point
		let vec2a = p5.Vector.sub(connectionA, this.anchor);
		this.angle = vec2a.heading();
	}
	update() {
		if (this.alock != null) {
			this.updateAngle_connectionA(this.alock);
		}
		let aoff = p5.Vector.fromAngle(this.angle);
		let boff = p5.Vector.fromAngle(this.angle + PI);
		aoff.setMag(this.lenL);
		boff.setMag(this.lenR);
		this.pinA.x = this.anchor.x + aoff.x;
		this.pinA.y = this.anchor.y + aoff.y;
		this.pinB.x = this.anchor.x + boff.x;
		this.pinB.y = this.anchor.y + boff.y;
	}
	render() {

		let lvec = p5.Vector.sub(this.pinB, this.pinA);
		let perp = p5.Vector.fromAngle(lvec.heading() + HALF_PI);
		perp.setMag(10);
		line(this.pinA.x, this.pinA.y, this.pinB.x, this.pinB.y);
		line(this.pinA.x + perp.x, this.pinA.y + perp.y, this.pinB.x + perp.x, this.pinB.y + perp.y);
		line(this.pinA.x - perp.x, this.pinA.y - perp.y, this.pinB.x - perp.x, this.pinB.y - perp.y);

	}
}

class Rocker {
	//maybe metronome is better name? oscillates between min and max angles  
	constructor(inposA, inLen, inAng0, inAng1) {
		this.anchor = inposA;
		this.len = inLen;
		this.angMin = inAng0;
		this.angMax = inAng1;
		this.angle = this.angMin;
		this.pin = createVector(0, 0);
		this.period = 100;
		this.dir = 1;
		this.tweenMode = false;
		this.tv = 0;
		this.position = this.anchor;
	}
	update() {
		if (this.tweenMode) {
			this.angle = map(this.tv, 0, 1, this.angMin, this.angMax);

		} else {
			let velo = (this.angMax - this.angMin) / this.period;
			this.angle += (velo * this.dir);
			if (this.angle > this.angMax) {
				this.angle = this.angMax;
				this.dir *= -1;
			} else if (this.angle < this.angMin) {
				this.angle = this.angMin;
				this.dir *= -1;
			}
		}

		this.pin.x = cos(this.angle) * this.len;
		this.pin.y = sin(this.angle) * this.len;
		this.pin.add(this.anchor);
	}

	render() {
		line(this.anchor.x, this.anchor.y, this.pin.x, this.pin.y);
	}
}

class Slider {
	//pin slides from posA to posB and back
	constructor(inposA, inposB) {
		this.posA = inposA;
		this.posB = inposB;
		this.pin = createVector(0, 0);
		this.period = 200;
		this.tick = 0;
		this.dir = 1;
		this.position = this.posA;
	}
	update() {
		this.tick++;
		this.tick %= this.period;
		if (this.tick == 0) {
			this.dir *= -1;
		}
		let tv = this.tick / this.period;
		if (this.dir < 0) {
			tv = 1 - tv;
		}
		let px = lerp(this.posA.x, this.posB.x, tv);
		let py = lerp(this.posA.y, this.posB.y, tv);
		this.pin.x = px;
		this.pin.y = py;
	}
	render() {
		line(this.posA.x, this.posA.y, this.posB.x, this.posB.y);
		circle(this.pin.x, this.pin.y, 5);
	}
}

class SquareWheel {
	//drives pin along perimeter of square shape
	constructor(inpos, insidelen) {
		this.position = inpos;
		this.sidelen = insidelen;
		this.dir = 1;
		this.period = 100;
		this.t = 0;
		this.pin = createVector(0, 0);
	}
	update() {
		this.t++;
		this.t %= this.period;
		let tv = this.t / this.period;
		let onside = floor(tv * 4);
		let partside = (tv * 4) - onside;
		let startx;
		let starty;
		let endx;
		let endy;
		let halfside = this.sidelen * 0.5;
		if (onside == 0) {
			startx = this.position.x - halfside;
			starty = this.position.y - halfside;
			endx = this.position.x + halfside;
			endy = this.position.y - halfside;
		} else if (onside == 1) {
			startx = this.position.x + halfside;
			starty = this.position.y - halfside;
			endx = this.position.x + halfside;
			endy = this.position.y + halfside;
		} else if (onside == 2) {
			startx = this.position.x + halfside;
			starty = this.position.y + halfside;
			endx = this.position.x - halfside;
			endy = this.position.y + halfside;
		} else if (onside == 3) {
			startx = this.position.x - halfside;
			starty = this.position.y + halfside;
			endx = this.position.x - halfside;
			endy = this.position.y - halfside;
		}
		let px = lerp(startx, endx, partside);
		let py = lerp(starty, endy, partside);
		this.pin.x = px;
		this.pin.y = py;
	}
	render() {
		rectMode(CENTER);
		noFill();
		strokeWeight(4);
		rect(this.position.x, this.position.y, this.sidelen, this.sidelen);
		fill(color('black'));
		strokeWeight(1);
		circle(this.pin.x, this.pin.y, 15);
		rect(this.position.x, this.position.y + (this.sidelen * 0.25), 20, this.sidelen * 0.5);
		rectMode(CORNER);
	}
}


